    $sequences{$current_header} = $current_seq;
}
close($fh);

my $input = $sequences{input};
my $output = $sequences{output};

# For circular plasmids, find the best alignment by rotating
my $best_score = -1;
my $best_offset = 0;

for my $offset (0 .. length($input)-1) {
    my $rotated = substr($input, $offset) . substr($input, 0, $offset);
    my $matches = 0;
    for my $i (0 .. length($output)-1) {
        last if $i >= length($rotated);
        $matches++ if substr($rotated, $i, 1) eq substr($output, $i, 1);
    }
    if ($matches > $best_score) {
        $best_score = $matches;
        $best_offset = $offset;
    }
}

print "Best alignment at offset $best_offset with $best_score matches\n";

my $aligned_input = substr($input, $best_offset) . substr($input, 0, $best_offset);

# Find the changed region
my $change_start = -1;
my $change_end_input = -1;
my $change_end_output = -1;

for my $i (0 .. length($output)-1) {
    if ($i >= length($aligned_input) || substr($aligned_input, $i, 1) ne substr($output, $i, 1)) {
        if ($change_start == -1) {
            $change_start = $i;
        }
        $change_end_output = $i;
    }
}

# Find where the sequences match again
my $match_start = -1;
for my $i ($change_end_output+1 .. length($output)-1) {
    my $window_len = 50;
    if ($i + $window_len <= length($output)) {
        my $out_window = substr($output, $i, $window_len);
        for my $j ($change_end_output+1 .. length($aligned_input)-1) {
            if ($j + $window_len <= length($aligned_input)) {
                my $inp_window = substr($aligned_input, $j, $window_len);
                if ($out_window eq $inp_window) {
                    $match_start = $j;
                    $change_end_input = $j;
                    last;
                }
            }
        }
        last if $match_start != -1;
    }
}

if ($match_start == -1) {
    # Try smaller windows
    for my $win (20, 15, 10) {
        for my $i ($change_end_output+1 .. length($output)-1) {
            if ($i + $win <= length($output)) {
                my $out_window = substr($output, $i, $win);
