#!/usr/bin/perl
use strict;
use warnings;

# Read sequences
open(my $fh, '<', '/app/sequences.fasta') or die "Cannot open: $!";
my %seq;
my $header;
my $s = '';

while (<$fh>) {
    chomp;
    if (/^>(.+)$/) {
        $seq{$header} = $s if $header;
        $header = $1;
        $s = '';
    } else {
        $s .= $_;
    }
}
$seq{$header} = $s if $header;
close($fh);

my $template = $seq{input};
my $insert = "tagattagaagaagaattaagaagaagattaacagaaag";
my $insert_pos = 215;

# For circular plasmid, we need primers that span the insertion point
# Strategy: forward primer ends with start of insert, reverse primer starts with end of insert

# Context around insertion point
my $prefix_len = 50;
my $suffix_len = 50;

my $prefix = substr($template, $insert_pos - $prefix_len, $prefix_len);
my $suffix = substr($template, $insert_pos, $suffix_len);

print "Insertion at position $insert_pos\n";
print "Prefix (50bp before): $prefix\n";
print "Suffix (50bp after): $suffix\n";
print "Insert sequence: $insert\n";
print "Insert length: " . length($insert) . " bp\n\n";

# Design forward primer: use prefix + start of insert
# Design reverse primer: use reverse complement of (suffix + end of insert)

sub reverse_complement {
    my ($seq) = @_;
    my $rev = reverse($seq);
    $rev =~ tr/ACGT/TGCA/;
    return $rev;
}

sub get_tm {
    my ($seq) = @_;
    my $result = `oligotm -tp 1 -sc 1 -mv 50 -dv 2 -n 0.8 -d 500 '$seq' 2>&1`;
    chomp($result);
    if ($result =~ /^\d+\./) {
        return $result;
    }
    return undef;
}

my @primer_pairs;

# Try different combinations of primer lengths
for my $f_prefix_len (10..30) {  # How much of prefix to include in forward primer
    for my $f_insert_len (5..20) {  # How much of insert to include in forward primer
        my $f_overlap_in_template = $f_prefix_len + $f_insert_len;
        next if $f_overlap_in_template > 45 || $f_overlap_in_template < 15;

        # Forward primer: prefix end + start of insert
        my $f_template_part = substr($template, $insert_pos - $f_prefix_len, $f_prefix_len);
        my $f_insert_part = substr($insert, 0, $f_insert_len);
        my $forward = $f_template_part . $f_insert_part;

        # Template part is what anneal to input
        my $f_tm = get_tm($f_template_part);
        next unless defined $f_tm;
        next if $f_tm < 58 || $f_tm > 72;

        # Reverse primer: reverse complement of (suffix + end of insert)
        for my $r_suffix_len (10..30) {
            for my $r_insert_len (5..20) {
                my $r_overlap_in_template = $r_suffix_len + $r_insert_len;
                next if $r_overlap_in_template > 45 || $r_overlap_in_template < 15;

                # Reverse primer should anneal to suffix end + end of insert (reverse complement)
                my $r_template_part = substr($template, $insert_pos + $suffix_len - $r_suffix_len, $r_suffix_len);
                my $r_insert_part = substr($insert, length($insert) - $r_insert_len, $r_insert_len);
                my $r_sequence = reverse_complement($r_template_part . $r_insert_part);

                my $r_tm = get_tm($r_template_part);
                next unless defined $r_tm;
                next if $r_tm < 58 || $r_tm > 72;

                # Check Tm difference
                my $tm_diff = abs($f_tm - $r_tm);
                next if $tm_diff > 5;

                push @primer_pairs, {
                    f_forward => $forward,
                    f_reverse => $r_sequence,
                    f_tm => $f_tm,
                    r_tm => $r_tm,
                    tm_diff => $tm_diff,
                    f_anneal_len => $f_prefix_len,
