    my $rev = reverse($seq);
    $rev =~ tr/ACGT/TGCA/;
    return $rev;
}

sub get_tm {
    my ($seq) = @_;
    return undef if length($seq) < 2;
    my $result = `oligotm -tp 1 -sc 1 -mv 50 -dv 2 -n 0.8 -d 500 '$seq' 2>&1`;
    chomp($result);
    if ($result =~ /^(\d+\.\d+)/) {
        return $1;
    }
    return undef;
}

my @candidates;

