#!/usr/bin/perl
use strict;
use warnings;

open(my $fh, '<', '/app/sequences.fasta') or die "Cannot open: $!";
my %seq;
my $header;
my $s = '';

while (<$fh>) {
    chomp;
    if (/^>(.+)$/) {
        $seq{$header} = $s if $header;
        $header = $1;
        $s = '';
    } else {
        $s .= $_;
    }
}
$seq{$header} = $s if $header;
close($fh);

my $template = $seq{input};
my $desired = $seq{output};

# For circular plasmids, try all rotations of template
my $best_match_score = 0;
my $best_offset = 0;

for my $offset (0 .. length($template)-1) {
    my $rotated = substr($template, $offset) . substr($template, 0, $offset);
    my $matches = 0;
    for my $i (0 .. length($desired)-1) {
        last if $i >= length($rotated);
        $matches++ if substr($rotated, $i, 1) eq substr($desired, $i, 1);
    }
    if ($matches > $best_match_score) {
        $best_match_score = $matches;
        $best_offset = $offset;
    }
}

my $rotated = substr($template, $best_offset) . substr($template, 0, $best_offset);
print "Best alignment offset: $best_offset\n";
print "Matches: $best_match_score / " . length($desired) . "\n\n";

# Find all difference regions
my @diffs;
my $i = 0;
my $in_diff = 0;
my $diff_start;

while ($i < length($desired)) {
    my $is_match = ($i < length($rotated) && substr($rotated, $i, 1) eq substr($desired, $i, 1));

    if (!$is_match && !$in_diff) {
        $diff_start = $i;
        $in_diff = 1;
    } elsif ($is_match && $in_diff) {
        push @diffs, {start => $diff_start, end => $i - 1};
        $in_diff = 0;
    }
    $i++;
}
push @diffs, {start => $diff_start, end => $i - 1} if $in_diff;

print "Found " . scalar(@diffs) . " difference regions:\n\n";

foreach my $diff (@diffs) {
    my $start = $diff->{start};
    my $end = $diff->{end};
    my $len = $end - $start + 1;

    print "Diff region: $start to $end ($len bp)\n";
    print "  Template: " . substr($rotated, $start, $len) . "\n";
    print "  Desired:  " . substr($desired, $start, $len) . "\n";
    print "  Context before: " . substr($rotated, $start - 20, 20) . "\n";
    print "  Context after: " . substr($rotated, $end + 1, 20) . "\n\n";
}
